'use strict';
(function(){
  const $=s=>document.querySelector(s); let client=null; const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function status(message,error=false){$('#adminGateStatus').textContent=message;$('#adminGateStatus').className=error?'is-error':'';}
  async function boot(){client=window.oramachiSupabase;if(!client)return status('Supabase設定を読み込めません。',true);const {data}=await client.auth.getSession();if(data.session)await authorize();}
  async function authorize(){const {data,error}=await client.rpc('is_app_admin');if(error||!data){await client.auth.signOut();return status('管理者権限がありません。',true);}$('#adminGate').hidden=true;$('#adminApp').hidden=false;$('#adminSignOut').hidden=false;open('reports');}
  $('#adminLogin').addEventListener('submit',async e=>{e.preventDefault();status('確認しています…');const {error}=await client.auth.signInWithPassword({email:$('#adminEmail').value,password:$('#adminPassword').value});if(error)return status('ログインできませんでした。',true);authorize();});
  $('#adminSignOut').addEventListener('click',async()=>{await client.auth.signOut();location.reload();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>open(b.dataset.tab));
  async function open(tab){$('#adminContent').innerHTML='<p>読み込んでいます…</p>';try{if(tab==='reports')return reports();if(tab==='questions-reports')return questionReports();if(tab==='users')return users();if(tab==='questions')return questions();if(tab==='daily')return daily();if(tab==='trivia')return trivia();if(tab==='audit')return audit();}catch(e){$('#adminContent').innerHTML='<p class="is-error">通信に失敗しました。接続を確認して、もう一度お試しください</p><button onclick="location.reload()">再試行</button>';}}
  async function reports(){const {data,error}=await client.from('user_reports').select('id,target_user_id,reason,details,status,created_at').order('created_at',{ascending:false}).limit(100);if(error)throw error;$('#adminContent').innerHTML='<h2>通報管理</h2>'+table(['日時','対象','理由','状態'],data.map(r=>[new Date(r.created_at).toLocaleString('ja-JP'),r.target_user_id,r.reason,`<select onchange="window.setReportStatus('${r.id}',this.value)">${['pending','reviewing','resolved','dismissed'].map(x=>`<option ${x===r.status?'selected':''}>${x}</option>`).join('')}</select>`]));}
  window.setReportStatus=async(id,status)=>{await client.from('user_reports').update({status,updated_at:new Date().toISOString()}).eq('id',id);};
  async function questionReports(){const {data,error}=await client.from('question_reports').select('*').order('created_at',{ascending:false}).limit(100);if(error)throw error;$('#adminContent').innerHTML='<h2>問題・質問の報告</h2>'+table(['日時','自治体','質問','表示','状態'],data.map(r=>[new Date(r.created_at).toLocaleString('ja-JP'),esc(r.municipality_name||r.municipality_id||'-'),esc(r.question_text),r.displayed_answer===null?'-':r.displayed_answer?'Yes':'No',esc(r.status)]));}
  async function users(){const q=prompt('ユーザー名（空欄で最近のユーザー）','')??'';let req=client.from('profiles').select('id,display_name,bio,current_rating,highest_rating,rated_matches,avatar_url').limit(100);if(q.trim())req=req.ilike('display_name',`%${q.trim()}%`);const {data,error}=await req;if(error)throw error;$('#adminContent').innerHTML='<h2>ユーザー</h2>'+table(['画像','ユーザー名','レート','最高','対戦数','運営操作'],data.map(x=>[x.avatar_url?`<img src="${esc(x.avatar_url)}" alt="" width="56" height="56" style="border-radius:50%;object-fit:cover" referrerpolicy="no-referrer">`:'未設定',esc(x.display_name),x.current_rating,x.highest_rating,x.rated_matches,x.avatar_url?`<button class="is-danger" onclick="window.removeProfileImage('${x.id}')">不適切画像を削除</button>`:'-']));}
  window.removeProfileImage=async userId=>{const reason=prompt('削除理由を入力してください（監査記録に残ります）','不適切なプロフィール画像');if(!reason?.trim())return;if(!confirm('このユーザーのプロフィール画像を削除し、仮アイコンへ戻しますか？'))return;const {error}=await client.functions.invoke('moderate-profile-image',{body:{target_user_id:userId,reason:reason.trim()}});if(error)return alert('画像を削除できませんでした。権限と通信状態を確認してください。');alert('プロフィール画像を削除し、運営対応を記録しました。');users();};
  async function questions(){const {data,error}=await client.from('managed_questions').select('*').order('updated_at',{ascending:false});if(error)throw error;$('#adminContent').innerHTML=`<h2>質問データ</h2><button id="newQuestion">新しい質問を作成</button>${table(['質問ID','質問文','カテゴリ','状態','操作'],data.map(q=>[esc(q.question_key),esc(q.text),esc(q.category),esc(q.status),`<button onclick="window.previewQuestion('${q.id}')">プレビュー</button> <button onclick="window.cloneQuestion('${q.id}')">複製</button>`]))}`;$('#newQuestion').onclick=createDraft;}
  async function createDraft(){const text=prompt('質問文');if(!text)return;const category=prompt('カテゴリ: geography/nature/transport/government/facility/industry/culture_history/other','geography')||'other';const {data,error}=await client.rpc('create_question_draft',{p_text:text,p_category:category,p_target_region:'全国',p_answer_mode:'yes_selected'});if(error)return alert(error.message);alert(`下書きを作成しました。質問ID: ${data}\n自治体回答を設定してからプレビューしてください。`);questions();}
  window.previewQuestion=async id=>{const [{data:q},{data:a}]=await Promise.all([client.from('managed_questions').select('*').eq('id',id).single(),client.from('managed_question_answers').select('answer').eq('question_id',id)]);const yes=(a||[]).filter(x=>x.answer===true).length,no=(a||[]).filter(x=>x.answer===false).length,unset=1741-yes-no;alert(`${q.text}\nYes：${yes}自治体／No：${no}自治体／未設定：${Math.max(0,unset)}自治体\n${yes===0||unset>0?'警告：回答設定を確認してください。':'公開可能です。'}`);};
  window.cloneQuestion=async id=>{const {data:q}=await client.from('managed_questions').select('*').eq('id',id).single();const {error}=await client.rpc('create_question_draft',{p_text:q.text,p_category:q.category,p_target_region:q.target_region,p_answer_mode:q.answer_mode,p_base_question_key:q.question_key});if(error)return alert(error.message);alert('複製した下書きを作成しました。');questions();};
  async function daily(){const [{data:rows,error},citiesRes]=await Promise.all([client.from('daily_challenge_schedule').select('challenge_date,municipality_name,prefecture_name,is_published,updated_at').order('challenge_date',{ascending:true}).limit(120),fetch('cities.json')]);if(error)throw error;const cities=await citiesRes.json();window.__dailyCities=cities;const options=cities.filter(c=>c.name!=='東京').map(c=>`<option value="${esc(c.pref+'|'+c.name)}">${esc(c.pref+' '+c.name)}</option>`).join('');$('#adminContent').innerHTML=`<h2>デイリー出題管理</h2><p>日付は日本時間です。公開後の当日分変更は進行中の挑戦へ影響するため避けてください。</p><form id="dailyForm"><label>出題日 <input id="dailyDate" type="date" required></label><label>自治体 <select id="dailyCity" required><option value="">選択してください</option>${options}</select></label><label><input id="dailyPublish" type="checkbox"> 公開する</label><button>保存</button></form>${table(['日付','自治体','状態','更新'],(rows||[]).map(r=>[r.challenge_date,esc(r.prefecture_name+' '+r.municipality_name),r.is_published?'公開':'下書き',new Date(r.updated_at).toLocaleString('ja-JP')]))}`;$('#dailyForm').onsubmit=saveDaily;}
  async function saveDaily(e){e.preventDefault();const city=window.__dailyCities.find(c=>`${c.pref}|${c.name}`===$('#dailyCity').value);if(!city)return alert('自治体を選択してください。');if($('#dailyPublish').checked&&!confirm('この出題を公開しますか？'))return;const keys=Array.isArray(city.tags)?city.tags:Object.keys(city.tags||{}).filter(k=>city.tags[k]);const {error}=await client.rpc('admin_upsert_daily_challenge',{p_date:$('#dailyDate').value,p_municipality_id:`${city.pref}|${city.name}`,p_municipality_name:city.name,p_prefecture_name:city.pref,p_answer_data:Object.fromEntries(keys.map(k=>[k,true])),p_publish:$('#dailyPublish').checked});if(error)return alert(error.message);alert('デイリー出題を保存しました。');daily();}
  async function trivia(){const [{data:rows,error},citiesRes]=await Promise.all([client.from('municipality_trivia').select('*').order('updated_at',{ascending:false}).limit(200),fetch('cities.json')]);if(error)throw error;const cities=(await citiesRes.json()).filter(c=>c.name!=='東京');window.__triviaCities=cities;const options=cities.map(c=>`<option value="${esc(c.pref+'|'+c.name)}">${esc(c.pref+' '+c.name)}</option>`).join('');$('#adminContent').innerHTML=`<h2>まち豆知識管理</h2><form id="triviaForm"><input id="triviaId" type="hidden"><label>自治体検索 <input id="triviaSearch" placeholder="市区町村名・都道府県名"></label><label>自治体 <select id="triviaCity" required><option value="">選択してください</option>${options}</select></label><label>見出し <input id="triviaTitle" maxlength="100" required></label><label>本文 <textarea id="triviaBody" maxlength="240" required></textarea></label><label>出典名 <input id="triviaSource" maxlength="160" required></label><label>出典URL <input id="triviaUrl" type="url" pattern="https://.*" required></label><label>確認日 <input id="triviaVerified" type="date" required></label><label>状態 <select id="triviaStatus"><option>draft</option><option>published</option><option>suspended</option></select></label><label>表示優先度 <input id="triviaPriority" type="number" value="0"></label><button>保存</button></form>${table(['自治体','見出し','状態','確認日','操作'],(rows||[]).map(r=>[esc(r.municipality_id),esc(r.title),esc(r.status),esc(r.verified_at),`<button onclick="window.editTrivia('${r.id}')">編集</button> <button onclick="window.stopTrivia('${r.id}')">公開停止</button>`]))}`;window.__triviaRows=rows||[];$('#triviaForm').onsubmit=saveTrivia;$('#triviaSearch').oninput=e=>{const q=e.target.value.trim();const found=cities.find(c=>(c.pref+c.name).includes(q));if(found)$('#triviaCity').value=`${found.pref}|${found.name}`;};}
  window.editTrivia=id=>{const r=window.__triviaRows.find(x=>x.id===id);if(!r)return;$('#triviaId').value=r.id;$('#triviaCity').value=r.municipality_id;$('#triviaTitle').value=r.title;$('#triviaBody').value=r.body;$('#triviaSource').value=r.source_name;$('#triviaUrl').value=r.source_url;$('#triviaVerified').value=r.verified_at;$('#triviaStatus').value=r.status;$('#triviaPriority').value=r.display_priority;scrollTo(0,0);};
  window.stopTrivia=async id=>{if(!confirm('この豆知識を公開停止しますか？'))return;const {error}=await client.from('municipality_trivia').update({status:'suspended',updated_at:new Date().toISOString()}).eq('id',id);if(error)return alert(error.message);trivia();};
  async function saveTrivia(e){e.preventDefault();const {data:{user}}=await client.auth.getUser();const payload={municipality_id:$('#triviaCity').value,title:$('#triviaTitle').value.trim(),body:$('#triviaBody').value.trim(),source_name:$('#triviaSource').value.trim(),source_url:$('#triviaUrl').value.trim(),verified_at:$('#triviaVerified').value,status:$('#triviaStatus').value,display_priority:Number($('#triviaPriority').value)||0,updated_by:user.id,updated_at:new Date().toISOString()};const id=$('#triviaId').value;const result=id?await client.from('municipality_trivia').update(payload).eq('id',id):await client.from('municipality_trivia').insert({...payload,created_by:user.id});if(result.error)return alert(result.error.message);alert(id?'豆知識を更新しました。':'豆知識を作成しました。');trivia();}
  async function audit(){const {data,error}=await client.from('admin_audit_log').select('*').order('created_at',{ascending:false}).limit(200);if(error)throw error;$('#adminContent').innerHTML='<h2>変更履歴</h2>'+table(['日時','対象','操作','管理者'],data.map(x=>[new Date(x.created_at).toLocaleString('ja-JP'),`${esc(x.target_type)} ${esc(x.target_id)}`,esc(x.action),esc(x.actor_id)]));}
  function table(head,rows){return `<div class="admin-table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  addEventListener('DOMContentLoaded',boot);
})();
